@Composable
fun GeneratedAppleLayout(
    mapController: ConsumerMapController,
    sheetController: com.example.applemaps.ui.components.AppleSheetController? = null,
    pin: MapCoordinate? = null,
    showBalloon: Boolean = true,   // false = minimize the balloon to just the ground dot
    pinTint: androidx.compose.ui.graphics.Color = androidx.compose.ui.graphics.Color(0xFFFF3B30),
    pinFace: androidx.compose.ui.graphics.ImageBitmap? = null,
    pinLabel: String = "Marked Location",
    baseSheetVisible: Boolean = true,   // false while the place card covers it (Back restores it)
    chromeVisible: Boolean = true,      // false in navigation mode (hide map-type/locate buttons + legal links)
    buildings3DEnabled: Boolean = true,
    onMapLongClick: (MapCoordinate) -> Unit = {},
    onPlaceSelected: (ConsumerSelectedPlace) -> Unit = {},
    onMapGesture: () -> Unit = {},
    placeHeader: (@Composable ColumnScope.() -> Unit)? = null,
    placeBody: (@Composable ColumnScope.() -> Unit)? = null,
    onMapType: () -> Unit = {},
    onLocate: () -> Unit = {},
    locationEnabled: Boolean = false,
    onSearch: () -> Unit = {},
    homeContent: AppleHomeContent? = null,
    homeLoading: Boolean = true,
    homeError: String? = null,
    onCategory: (AppleHomeCategory) -> Unit = {},
    onGuide: (String) -> Unit = {},
    collapsedPeek: androidx.compose.ui.unit.Dp? = null,   // place-card state uses a shorter peek (name only)
) {
    Box(Modifier.fillMaxSize()) {
        MapSurface(mapController, Modifier.fillMaxSize(), pin = pin, showBalloon = showBalloon, pinTint = pinTint, pinFace = pinFace, pinLabel = pinLabel, onMapLongClick = onMapLongClick, onPlaceSelected = onPlaceSelected, onMapGesture = onMapGesture, locationEnabled = locationEnabled, buildings3DEnabled = buildings3DEnabled)

        // topRightMapControls — white 44dp map-mode/location pill. Geometry-only corner reveal on
        // navigation enter/exit; opacity is intentionally unchanged so expansion is not mixed with a fade.
        AnimatedVisibility(
            visible = chromeVisible,
            enter = expandIn(tween(250), expandFrom = Alignment.TopEnd),
            exit = shrinkOut(tween(220), shrinkTowards = Alignment.TopEnd),
            modifier = Modifier.align(Alignment.TopEnd),
        ) {
            Column(Modifier.statusBarsPadding().padding(top = 20.dp, end = 10.dp)) {
                AppleControlButton(R.drawable.ic_map_fill_semibold, R.string.cd_map_type,
                    size = 44.dp, shape = RoundedCornerShape(topStart = 12.dp, topEnd = 12.dp, bottomEnd = 0.dp, bottomStart = 0.dp), onClick = onMapType)
                AppleControlButton(R.drawable.ic_location_semibold, R.string.cd_current_location,
                    size = 44.dp, shape = RoundedCornerShape(topStart = 0.dp, topEnd = 0.dp, bottomEnd = 12.dp, bottomStart = 12.dp), onClick = onLocate)
            }
        }

        // bottomLegalLinks — legal attribution is the one approved chrome element that fades.
        AnimatedVisibility(visible = chromeVisible, enter = fadeIn(tween(250)), exit = fadeOut(tween(200)),
            modifier = Modifier.align(Alignment.BottomCenter)) {
            LegalLinks(Modifier.padding(bottom = 122.dp))
        }

        // bottom sheet — measured 124dp peek; user-lowered 116dp rest hides clipped Find Nearby text
        if (baseSheetVisible) {
        AppleBottomSheet(
            peekHeight = collapsedPeek ?: 116.dp,
            topRadius = 14.dp,   // iOS-style corner (web measured 12px; user override)
