                    AppleSearchField(
                        Modifier.padding(start = 16.dp, end = 16.dp, top = 0.dp).fillMaxWidth(),
                        onClick = onSearch,
                    )
                }
            },
            body = { if (placeBody != null) placeBody() else HomeFrontPage(homeContent, homeLoading, homeError, onCategory, onGuide) },
